import {createServer} from 'node:http';import {spawn} from 'node:child_process';import {createInterface} from 'node:readline';
const c=spawn(process.execPath,['plugins/matrix-bridge/mcp/server.mjs'],{cwd:process.cwd()});c.stdin.write(JSON.stringify({jsonrpc:'2.0',id:1,method:'resources/read',params:{uri:'ui://matrix-bridge/console.html'}})+'\n');const panel=await new Promise(resolve=>createInterface({input:c.stdout}).on('line',line=>resolve(JSON.parse(line).result.contents[0].text)));c.kill();
const host=`<!doctype html><html><body><iframe id="app" src="/panel" style="width:100%;height:95vh"></iframe><script>
const config={admins:['@admin:example.org'],allowed_senders:['*'],invite_policy:'all',message_policy:'all',cwd:'/tmp',default_policy:'mention'};const room={id:'!test:example.org',name:'测试房间',workspace:'/tmp',policy:'mention',model:'',effort:'',migration_candidates:[],pending:[]};
window.addEventListener('message',e=>{const m=e.data;if(!m||m.id===undefined)return;let result;if(m.method==='ui/initialize')result={protocolVersion:'2026-01-26',hostInfo:{name:'test-host',version:'1.0.0'},hostCapabilities:{serverTools:{}},hostContext:{}};else if(m.method==='tools/call'){const n=m.params.name;let data={ok:true};if(n==='matrix_bridge_status')data={running:true,configured:true,sync_state:'online',homeserver:'https://example.org',user_id:'@bot:example.org',blocked_rooms:0};if(n==='matrix_bridge_config')data=config;if(n==='matrix_bridge_rooms')data={rooms:[room]};if(n==='matrix_bridge_models')data={models:[],settings:{}};if(n==='matrix_bridge_logs')data={logs:[]};if(n==='matrix_bridge_update_room')Object.assign(room,m.params.arguments);result={content:[{type:'text',text:JSON.stringify(data)}]};}else return;e.source.postMessage({jsonrpc:'2.0',id:m.id,result},'*');});
</script></body></html>`;
createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(req.url==='/panel'?panel:host)}).listen(47640,'127.0.0.1',()=>console.log('mock host ready'));
